"""gen_menu.py -- hierarchical MenuBuilder generator.

Reads cli/cli_commands.txt (format: cli/MenuBuilder_hierarchical.md) and writes
  cli/menu_table.c        command, mode and keyword tables for menu.c
  cli/menu_commands.h     callback prototypes
  cli/MenuDocumentation.md design document with Mermaid diagrams and the
                          command reference
Every output is a pure function of the .txt (the generation date is the date
of the newest REVISION line), so cli/check_menu.py can regenerate in memory and
compare byte for byte.

Usage: python gen_menu.py [--check]   (--check: compare, write nothing)
Exit: 0 written / identical, 1 input error or (with --check) a difference.
"""
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
TXT = os.path.join(HERE, "cli_commands.txt")

MODES = ["exec", "priv", "config", "config-if", "config-dhcp", "config-sock"]
ENUM = {m: "MENU_MODE_" + m.upper().replace("-", "_") for m in MODES}
BUILTINS = ["EXIT", "END", "HELP"]
CONFIG_TREE = {"config", "config-if", "config-dhcp", "config-sock"}

