class InputError(Exception):
    """A rule of the input format is broken (message names the line)."""


def c_str(s):
    """C string literal of s (ASCII only)."""
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


def parse_syntax(syntax, where):
    """Split a COMMAND field into (kind, text) tokens and check the rules."""
    toks = syntax.split()
    if not toks:
        raise InputError(f"{where}: empty command")
    out = []
    seen_opt = False
    for t in toks:
        if t.startswith("["):
            if not re.fullmatch(r"\[[A-Z][A-Z0-9_]*\]", t):
                raise InputError(f"{where}: bad required parameter '{t}'")
            if seen_opt:
                raise InputError(f"{where}: required parameter after an optional one")
            out.append(("req", t))
        elif t.startswith("{"):
            if not re.fullmatch(r"\{[A-Z][A-Z0-9_]*\}", t):
                raise InputError(f"{where}: bad optional parameter '{t}'")
            seen_opt = True
            out.append(("opt", t))
        else:
            if not re.fullmatch(r"[A-Z][A-Z0-9-]*", t):
                raise InputError(f"{where}: keyword '{t}' must be upper case letters, digits, '-'")
            if seen_opt:
                raise InputError(f"{where}: keyword after an optional parameter")
            out.append(("kw", t))
        if len(t) >= 24:
            raise InputError(f"{where}: token '{t}' longer than 23 characters (MENU_MAX_TOKEN_TEXT)")
    if len(out) > 14:
        raise InputError(f"{where}: more than 14 tokens (MENU_MAX_SYNTAX_TOKENS)")
    if sum(1 for kind, _ in out if kind != "kw") > 14:
        raise InputError(f"{where}: more than 14 parameters (MENU_MAX_ARGS)")
    return out


def load(path=TXT):
    """Parse the command file; return the model dictionary."""
    model = {"revisions": [], "modes": {}, "commands": [], "keywords": []}
    with open(path, encoding="utf-8") as fh:
        lines = fh.read().splitlines()
    for no, raw in enumerate(lines, 1):
        line = raw.strip()
        where = f"cli_commands.txt:{no}"
        if not line or line.startswith("#"):
            continue
        head = line.split(":", 1)[0]
        if head == "REVISION":
            f = line.split(":", 2)
            if len(f) != 3 or not re.fullmatch(r"\d\d-\d\d-\d\d\d\d", f[1]):
                raise InputError(f"{where}: REVISION:<MM-DD-YYYY>:<change>")
            model["revisions"].append((f[1], f[2].strip()))
        elif head == "MODE-ROOT":
            f = line.split(":", 3)
            if len(f) != 4 or f[1] not in MODES:
                raise InputError(f"{where}: MODE-ROOT:<mode>:<prompt>:<description>")
            if f[1] in model["modes"]:
                raise InputError(f"{where}: mode {f[1]} defined twice")
            model["modes"][f[1]] = {"prompt": f[2], "parent": None, "desc": f[3].strip()}
        elif head == "MODE-ENTER":
            f = line.split(":", 7)
            if len(f) != 8:
                raise InputError(f"{where}: MODE-ENTER needs 8 fields")
            _, func, frm, cmd, to, prompt, mdesc, desc = f
            if frm not in MODES or to not in MODES:
                raise InputError(f"{where}: unknown mode")
            if to in model["modes"]:
                raise InputError(f"{where}: mode {to} defined twice")
            if func != "-" and not re.fullmatch(r"[a-z_][a-z0-9_]*", func):
                raise InputError(f"{where}: FUNCTION must be lower_snake_case or '-'")
            model["modes"][to] = {"prompt": prompt, "parent": frm, "desc": mdesc.strip()}
            model["commands"].append({"func": func, "mode": frm, "syntax": cmd.strip(),
                                      "desc": desc.strip(), "enter": to, "line": no,
                                      "tokens": parse_syntax(cmd.strip(), where)})
        elif head == "KEYWORD":
            f = line.split(":", 3)
            if len(f) != 4 or f[1] not in MODES:
                raise InputError(f"{where}: KEYWORD:<mode>:<path>:<description>")
            for k in f[2].split():
                if not re.fullmatch(r"[A-Z][A-Z0-9-]*", k):
                    raise InputError(f"{where}: bad keyword path '{f[2]}'")
            model["keywords"].append({"mode": f[1], "path": " ".join(f[2].split()), "desc": f[3].strip()})
        else:
            f = line.split(":", 3)
            if len(f) != 4:
                raise InputError(f"{where}: FUNCTION:MODE:COMMAND:DESCRIPTION expected")
            func, mode, cmd, desc = f
            if not re.fullmatch(r"[a-z_][a-z0-9_]*", func):
                raise InputError(f"{where}: FUNCTION '{func}' must be lower_snake_case")
            if mode not in MODES:
                raise InputError(f"{where}: unknown mode '{mode}'")
            model["commands"].append({"func": func, "mode": mode, "syntax": cmd.strip(),
                                      "desc": desc.strip(), "enter": None, "line": no,
                                      "tokens": parse_syntax(cmd.strip(), where)})
    check(model)
    return model


def available(cmd_mode, mode):
    """Whether a command of cmd_mode can be typed in mode (exec is inherited by priv)."""
    return cmd_mode == mode or (mode == "priv" and cmd_mode == "exec")


def check(model):
    """Cross-line rules: every mode defined, no duplicates, no built-in clash."""
    for m in MODES:
        if m not in model["modes"]:
            raise InputError(f"mode {m} has no MODE-ROOT / MODE-ENTER line")
    roots = [m for m, d in model["modes"].items() if d["parent"] is None]
    if roots != ["exec"]:
        raise InputError("exactly one MODE-ROOT, for mode exec, is required")
    if not model["revisions"]:
        raise InputError("at least one REVISION line is required")
    funcs = {}
    for c in model["commands"]:
        if c["func"] != "-":
            if c["func"] in funcs:
                raise InputError(f"line {c['line']}: FUNCTION {c['func']} also on line {funcs[c['func']]}")
            funcs[c["func"]] = c["line"]
        if c["tokens"][0][1] in BUILTINS:
            raise InputError(f"line {c['line']}: '{c['tokens'][0][1]}' is a built-in command")
    for mode in MODES:
        seen = {}
        for c in model["commands"]:
            if not available(c["mode"], mode):
                continue
            shape = tuple(t[1] if t[0] == "kw" else "<p>" for t in c["tokens"])
            if shape in seen:
                raise InputError(f"line {c['line']}: same command shape as line {seen[shape]} in mode {mode}")
            seen[shape] = c["line"]


def min_max(tokens):
    """Minimum and maximum token counts of a parsed syntax."""
    mn = sum(1 for k, _ in tokens if k != "opt")
    return mn, len(tokens)


def gen_date(model):
    """Generation date: the newest REVISION date code (keeps the output reproducible)."""
    d = max(model["revisions"], key=lambda r: (r[0][6:], r[0][0:2], r[0][3:5]))[0]
    return f"{d[6:]}-{d[0:2]}-{d[3:5]} 00:00:00 -04:00"


def revision_block(model):
    rows = "".join(f" *  {d}  MenuBuilder AI / Steve Spano    {t}\n" for d, t in model["revisions"])
    return ("/*\n"
            " * ===========================================================================\n"
            " *  REVISION HISTORY\n"
            " * ===========================================================================\n"
            " *  Revision    Author                          Description\n"
            " * ---------------------------------------------------------------------------\n"
            f"{rows}"
            " * ===========================================================================\n"
            " */\n")


def gen_table_c(model):
    out = [LICENSE_C]
    out.append("/*\n"
               " * File:      menu_table.c\n"
               f" * Generated: {gen_date(model)}\n"
               " * Project:   RTLNet Nexys Video firmware, hierarchical CLI\n"
               " * Purpose:   Mode, command and keyword tables of the menu engine (menu.c).\n"
               " *            GENERATED by cli/gen_menu.py from cli/cli_commands.txt -- do not\n"
               " *            edit; change the .txt and regenerate (cli/check_menu.py verifies\n"
               " *            that this file matches the .txt).\n"
               " */\n")
    out.append(revision_block(model))
    out.append('#include "menu.h"\n#include "menu_commands.h"\n\n')
    out.append("/* Modes in MenuMode order: prompt and the mode `exit` returns to. */\n")
    out.append("const MenuModeDef g_menu_modes[] = {\n")
    for m in MODES:
        d = model["modes"][m]
        parent = ENUM[d["parent"]] if d["parent"] else "MENU_MODE_NONE"
        out.append(f"    {{ {ENUM[m]}, {c_str(m)}, {c_str(d['prompt'])}, {parent}, {c_str(d['desc'])} }},\n")
    out.append("};\nconst size_t g_menu_mode_count = sizeof(g_menu_modes) / sizeof(g_menu_modes[0]);\n\n")
    out.append("/* Commands: FUNCTION, MODE, COMMAND, DESCRIPTION, callback, mode entered. */\n")
    out.append("const MenuCommandDef g_menu_commands[] = {\n")
    for c in model["commands"]:
        cb = c["func"] if c["func"] != "-" else "NULL"
        enter = ENUM[c["enter"]] if c["enter"] else "MENU_MODE_NONE"
        out.append(f"    {{ {c_str(c['func'])}, {ENUM[c['mode']]}, {c_str(c['syntax'])},\n"
                   f"      {c_str(c['desc'])}, {cb}, {enter} }},\n")
    out.append("};\nconst size_t g_menu_command_count = sizeof(g_menu_commands) / sizeof(g_menu_commands[0]);\n\n")
    out.append("/* Help text of keywords shared by several commands. */\n")
    out.append("const MenuKeywordDef g_menu_keywords[] = {\n")
    for k in model["keywords"]:
        out.append(f"    {{ {ENUM[k['mode']]}, {c_str(k['path'])}, {c_str(k['desc'])} }},\n")
    out.append("};\nconst size_t g_menu_keyword_count = sizeof(g_menu_keywords) / sizeof(g_menu_keywords[0]);\n")
    return "".join(out)


def gen_commands_h(model):
    out = [LICENSE_C]
    out.append("/*\n"
               " * File:      menu_commands.h\n"
               f" * Generated: {gen_date(model)}\n"
               " * Project:   RTLNet Nexys Video firmware, hierarchical CLI\n"
               " * Purpose:   Prototypes of every command callback named in\n"
               " *            cli/cli_commands.txt; cli/cli_commands.c defines them.\n"
               " *            GENERATED by cli/gen_menu.py -- do not edit.\n"
               " */\n")
    out.append("#ifndef MENU_COMMANDS_H\n#define MENU_COMMANDS_H\n\n#include \"menu.h\"\n\n")
    for c in model["commands"]:
        if c["func"] != "-":
            out.append(f"int {c['func']}(const MenuCommandContext *ctx);\n")
    out.append("\n#endif /* MENU_COMMANDS_H */\n")
    return "".join(out)


def md_escape(s):
    return s.replace("|", "\\|")


def gen_doc(model):
    rev = model["revisions"][-1][0]
    cmds = model["commands"]
    out = [LICENSE_MD, "\n"]
    out.append("# RTLNet Nexys Video CLI — MenuDocumentation\n\n")
    out.append("| Item | Value |\n|---|---|\n")
    out.append(f"| Revision | {rev} (newest row of the revision history in cli/cli_commands.txt) |\n")
    out.append(f"| Generated | {gen_date(model)} by cli/gen_menu.py from cli/cli_commands.txt |\n")
    out.append(f"| Commands | {len(cmds)} table entries ({sum(1 for c in cmds if c['enter'])} mode-entry), "
               f"{len(model['keywords'])} keyword groups, 3 built-ins (exit, end, help) |\n\n")
    out.append("## 1. Title and overview\n\n"
               "The firmware console of the RTLNet Nexys Video board is a light-weight hierarchical command\n"
               "line in the style of a network switch: user exec (`rtlnet>`), privileged exec (`rtlnet#`,\n"
               "`enable`/`disable`), global configuration (`configure terminal`) and three configuration\n"
               "sub-modes. It follows the MenuBuilder rules (explicit `matched` dispatch, aligned help, HELP\n"
               "and `?` aliases, LGPL headers, revision table) extended by `MenuBuilder_hierarchical.md`:\n"
               "modes and prompts, `exit`/`end`/Ctrl-Z, context-sensitive `?`, unique-prefix abbreviation,\n"
               "backspace editing, history (`!!`, up/down arrow) and `no` forms.\n\n"
               "The same engine and command callbacks build for the MicroBlaze target (UART console, no C\n"
               "library) and for the desktop harness (stdin/stdout, register model), whose `--demo` session\n"
               "checks the parser and the mode logic.\n\n")
    out.append("## 2. Architecture overview\n\n```mermaid\ngraph TD\n"
               "    TXT[\"cli_commands.txt<br/>command set\"] -->|gen_menu.py| TABLE[\"menu_table.c / menu_commands.h<br/>generated tables\"]\n"
               "    MAIN[\"src/main.c (target)<br/>host/main.c (harness)\"] -->|Menu_InputChar| MENU[\"menu.c<br/>modes, parser, help, editor\"]\n"
               "    MENU -->|includes| MENUH[\"menu.h<br/>API and types\"]\n"
               "    MENU -->|reads| TABLE\n"
               "    MENU -->|dispatches to| CMDS[\"cli_commands.c<br/>command callbacks\"]\n"
               "    CMDS -->|board API| BOARD[\"src/rtlnet_board.c<br/>register owner\"]\n"
               "    BOARD -->|rtlnet_mmio.h| HW[\"RTLNet window 0x44A0_0000<br/>(host: register model)\"]\n"
               "    CMDS -->|fmt_printf| CON[\"console<br/>UART Lite / stdout\"]\n"
               "    MENU -->|MenuIo.write| CON\n```\n\n")
    out.append("## 3. Initialization flow\n\n```mermaid\nflowchart TD\n"
               "    A[\"Menu_Init(io)\"] --> B[\"For each entry of g_menu_commands[] then the built-ins\"]\n"
               "    B --> C[\"Tokenize the syntax by whitespace\"]\n"
               "    C --> E{\"Token starts with '[' ?\"}\n"
               "    E -- Yes --> F[\"REQUIRED param\"]\n"
               "    E -- No --> G{\"Token starts with '{' ?\"}\n"
               "    G -- Yes --> H[\"OPTIONAL param\"]\n"
               "    G -- No --> I[\"KEYWORD\"]\n"
               "    F --> J[\"Store in g_parsed[i].tokens[]\"]\n"
               "    H --> J\n    I --> J\n"
               "    J --> K{\"More tokens?\"}\n    K -- Yes --> E\n"
               "    K -- No --> L[\"min_tokens / max_tokens, valid flag\"]\n"
               "    L --> M{\"More commands?\"}\n    M -- Yes --> B\n"
               "    M -- No --> N[\"mode = exec, editor cleared, g_is_initialized = 1\"]\n```\n\n")
    out.append("## 4. Command processing and dispatch flow\n\n```mermaid\nflowchart TD\n"
               "    A[\"Menu_InputChar(c)\"] --> B{\"CR / LF ?\"}\n"
               "    B -- No --> B2{\"'?' / Ctrl-C / Ctrl-Z / BS / ESC [ A,B\"}\n"
               "    B2 --> B3[\"context help / cancel / end / erase / history\"]\n"
               "    B -- Yes --> C[\"Menu_ProcessLine(line)\"]\n"
               "    C --> D{\"empty?\"}\n    D -- Yes --> Z0[\"return 0\"]\n"
               "    D -- No --> E{\"'!!' ?\"}\n    E -- Yes --> E2[\"replay newest history line\"]\n"
               "    E -- No --> F{\"ends with '?' ?\"}\n    F -- Yes --> F2[\"help or context help\"]\n"
               "    F -- No --> G[\"store in history; tokenize\"]\n"
               "    G --> H[\"menu_resolve: per position exact keyword, else unique prefix, else parameter\"]\n"
               "    H --> I{\"resolved?\"}\n    I -- ambiguous / invalid --> Z1[\"print caret and error; return -1\"]\n"
               "    I -- Yes --> J[\"for each candidate: matched = 0\"]\n"
               "    J --> K[\"rc = menu_match_and_dispatch(idx, expanded, n, &matched)\"]\n"
               "    K --> L{\"matched == 1?\"}\n    L -- Yes --> M[\"return rc (mode entered if rc == 0)\"]\n"
               "    L -- No --> J\n    J -- none left --> P[\"'% Incomplete command.' or '% Unknown command'; return -1\"]\n```\n\n")
    out.append("## 5. Token matching detail\n\n```mermaid\nflowchart TD\n"
               "    A[\"menu_match_and_dispatch()\"] --> B{\"parsed.valid == 0?\"}\n"
               "    B -- Yes --> Z1[\"return -1 (invalid def)\"]\n"
               "    B -- No --> C{\"ntok in [min_tokens, max_tokens]?\"}\n"
               "    C -- No --> Z2[\"return -1 (count mismatch)\"]\n"
               "    C -- Yes --> D[\"For each syntax token i < ntok\"]\n"
               "    D --> E{\"Token type?\"}\n"
               "    E -- KEYWORD --> F{\"expanded[i] equals keyword (case-insensitive)?\"}\n"
               "    F -- No --> Z3[\"return -1 (keyword mismatch)\"]\n"
               "    F -- Yes --> G[\"continue\"]\n"
               "    E -- REQUIRED / OPTIONAL --> H[\"capture into ctx.argv[]\"]\n    H --> G\n"
               "    G --> I{\"More tokens?\"}\n    I -- Yes --> D\n"
               "    I -- No --> J{\"callback or enter_mode set?\"}\n    J -- No --> Z4[\"return -1\"]\n"
               "    J -- Yes --> K[\"*matched = 1\"]\n    K --> L[\"rc = callback(&ctx) (0 if none)\"]\n"
               "    L --> N{\"rc == 0 and enter_mode?\"}\n    N -- Yes --> O[\"Menu_SetMode(enter_mode)\"]\n"
               "    N -- No --> R[\"return rc\"]\n    O --> R\n```\n\n")
    out.append("## 6. Data structures\n\n```mermaid\nclassDiagram\n"
               "    class MenuCommandDef {\n        +const char* function_name\n        +MenuMode mode\n"
               "        +const char* syntax\n        +const char* description\n        +MenuCallback callback\n"
               "        +MenuMode enter_mode\n    }\n"
               "    class MenuModeDef {\n        +MenuMode mode\n        +const char* name\n        +const char* prompt\n"
               "        +MenuMode parent\n        +const char* description\n    }\n"
               "    class MenuKeywordDef {\n        +MenuMode mode\n        +const char* path\n        +const char* description\n    }\n"
               "    class MenuCommandContext {\n        +int argc\n        +const char* argv[MENU_MAX_ARGS]\n        +MenuMode mode\n    }\n"
               "    class ParsedCommand {\n        +ParsedToken tokens[MENU_MAX_SYNTAX_TOKENS]\n        +int token_count\n"
               "        +int min_tokens\n        +int max_tokens\n        +int valid\n    }\n"
               "    class ParsedToken {\n        +MenuTokenType type\n        +char text[32]\n    }\n"
               "    class MenuTokenType {\n        <<enumeration>>\n        MENU_TOKEN_KEYWORD\n"
               "        MENU_TOKEN_REQUIRED_PARAM\n        MENU_TOKEN_OPTIONAL_PARAM\n    }\n"
               "    MenuCommandDef --> MenuCommandContext : passes to callback\n"
               "    MenuCommandDef --> MenuModeDef : belongs to / enters\n"
               "    ParsedCommand *-- ParsedToken : contains\n"
               "    ParsedToken --> MenuTokenType : classified by\n```\n\n")
    out.append("### 6.1 Mode tree\n\n```mermaid\nstateDiagram-v2\n")
    for m in MODES:
        d = model["modes"][m]
        if d["parent"]:
            entry = [c for c in cmds if c["enter"] == m][0]
            out.append(f"    {d['parent'].replace('-', '_')} --> {m.replace('-', '_')} : {entry['syntax'].lower()}\n")
            out.append(f"    {m.replace('-', '_')} --> {d['parent'].replace('-', '_')} : exit\n")
    for m in sorted(CONFIG_TREE - {"config"}):
        out.append(f"    {m.replace('-', '_')} --> priv : end / Ctrl-Z\n")
    out.append("    config --> priv : end / Ctrl-Z\n    priv --> exec : disable\n```\n\n")
    out.append("| Mode | Prompt | Entered by | `exit` returns to |\n|---|---|---|---|\n")
    for m in MODES:
        d = model["modes"][m]
        entry = [c for c in cmds if c["enter"] == m]
        how = f"`{entry[0]['syntax'].lower()}` in {entry[0]['mode']}" if entry else "start-up"
        out.append(f"| {m} | `{d['prompt']}` | {how} | {d['parent'] or '— (stays)'} |\n")
    out.append("\n## 7. Command reference\n\n")
    out.append("One row per command line of cli/cli_commands.txt (MODE-ENTER lines included). Min/Max are\n"
               "token counts; exec commands are also accepted in priv.\n\n")
    out.append("| # | Function | Mode | Command Syntax | Required | Optional | Min | Max | Enters | Description |\n")
    out.append("|---|---|---|---|---|---|---|---|---|---|\n")
    for i, c in enumerate(cmds, 1):
        req = ", ".join(t[1:-1] for k, t in c["tokens"] if k == "req") or "—"
        opt = ", ".join(t[1:-1] for k, t in c["tokens"] if k == "opt") or "—"
        mn, mx = min_max(c["tokens"])
        out.append(f"| {i} | {c['func']} | {c['mode']} | `{c['syntax']}` | {req} | {opt} | {mn} | {mx} | "
                   f"{c['enter'] or '—'} | {md_escape(c['desc'])} |\n")
    out.append("\nBuilt-ins (menu.c): `EXIT` (every mode), `END` (privileged and configuration modes), `HELP` and `?`\n"
               "(every mode, identical listing), `!!` (repeat the previous line), Ctrl-C (cancel the line),\n"
               "Ctrl-Z (`end`), Ctrl-U (erase the line), up/down arrow (history).\n\n")
    out.append("Keyword groups (help text when `?` lists a keyword shared by several commands):\n\n")
    out.append("| Mode | Keyword path | Description |\n|---|---|---|\n")
    for k in model["keywords"]:
        out.append(f"| {k['mode']} | `{k['path']}` | {md_escape(k['desc'])} |\n")
    out.append("\n## 8. Build instructions\n\n"
               "Desktop harness (host gcc), from `cpu/microblaze_v_h264/firmware`:\n\n"
               "```\nbuild.bat          REM compile and link build/menu.exe\n"
               "build.bat run      REM build + interactive mode (stdin/stdout)\n"
               "build.bat demo     REM build + scripted session, prints TEST PASS/FAIL\n"
               "build.bat clean    REM remove build artifacts\n"
               "build.bat firmware REM MicroBlaze firmware build/firmware.elf (mb-gcc)\n```\n\n"
               "```\nmake               # compile and link build/menu.exe\nmake run           # interactive\n"
               "make demo          # scripted session\nmake clean\nmake firmware      # build/firmware.elf\n```\n\n"
               "PowerShell (both, plus the table check): `powershell -File build.ps1 [-Host] [-Demo] [-Check]`.\n"
               "After editing cli/cli_commands.txt run `python cli/gen_menu.py`, then `python cli/check_menu.py`.\n")
    return "".join(out)


OUTPUTS = {
    "menu_table.c": gen_table_c,
    "menu_commands.h": gen_commands_h,
    "MenuDocumentation.md": gen_doc,
}


def main(argv):
    check_only = "--check" in argv
    try:
        model = load()
    except InputError as e:
        print(f"gen_menu: ERROR {e}")
        return 1
    rc = 0
    for name, fn in OUTPUTS.items():
        text = fn(model)
        path = os.path.join(HERE, name)
        old = None
        if os.path.exists(path):
            # Line ends compare normalized: a checkout may carry CRLF
            # (core.autocrlf) while the generator writes LF.
            with open(path, encoding="utf-8", newline="") as fh:
                old = fh.read().replace("\r\n", "\n")
        if check_only:
            if old != text:
                print(f"gen_menu: DIFFERS {name} (run python cli/gen_menu.py)")
                rc = 1
        elif old != text:
            with open(path, "w", encoding="utf-8", newline="\n") as fh:
                fh.write(text)
            print(f"gen_menu: wrote {name}")
    if not check_only:
        print(f"gen_menu: {len(model['commands'])} commands, {len(MODES)} modes, {len(model['keywords'])} keyword groups")
    return rc


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
